$d=Sponsors::blank();$d['name']='QA measured sponsor';$d['url']='https://example.com/phase13-measurement';$d['status']='enabled';$d['ends_at']=gmdate('Y-m-d H:i:s',time()+3600);$d['review_note']='Synthetic measurement fixture';$d['translations']=['en_US'=>['title'=>'QA sponsor observations','description'=>'Synthetic local fixture.'],'zh_CN'=>['title'=>'QA 赞助统计','description'=>'仅用于隔离统计测试。']];$s=$sponsors->saveEntry(0,$sponsors->snapshot()['revision'],$d,true);$id=$s['entries'][array_key_last($s['entries'])]['id'];$sponsors->setEnabled(true,$s['revision']);
$_SERVER['HTTP_USER_AGENT']='Mozilla/5.0 Chrome/155.0.0.0 Safari/537.36';wp_set_current_user(0);$_COOKIE=[];
