p13_case('commercial_requires_distinct_consent_no_identity_or_destination_in_proof',function()use($views,$metrics,$proof,$persist,&$observer,&$data){p13_assert($views->commercialObserver()===null,'No implicit commercial consent');$views->grantAnalyticsConsent();p13_assert($views->commercialObserver()===null,'Analytics consent does not authorize sponsorship measurement');$views->withdrawAnalyticsConsent();$observer=$views->grantCommercialConsent();p13_assert($views->commercialObserver()===$observer&&$views->analyticsObserver()===null,'Commercial-only cookie does not authorize broader analytics');$data=$proof();foreach(['url','email','ip','user_id','review_note','observer']as$field)p13_assert(!array_key_exists($field,$data),'Proof excludes '.$field);p13_reject(fn()=>$persist->invoke($metrics,$data,'click',str_repeat('a',64)),'Forged observer rejected before persistence');});
p13_case('commercial_exact_observations_unique_daily_and_language_counters',function()use($views,$proof,$persist,$metrics,$count,$data,$observer){p13_assert($persist->invoke($metrics,$data,'impression',$observer),'First proof impression persisted');p13_assert(!$persist->invoke($metrics,$data,'impression',$observer),'Same proof impression replay deduped');p13_assert($persist->invoke($metrics,$data,'click',$observer),'Distinct click observation');p13_assert(!$persist->invoke($metrics,$data,'click',$observer),'Repeated click same proof deduped');$next=$proof();p13_assert($persist->invoke($metrics,$next,'impression',$observer),'New response same observer raw observation');p13_assert($count('sponsor_impression')===2&&$count('sponsor_impression_unique')===1,'Exact two impressions one daily observer');p13_assert($count('sponsor_click')===1&&$count('sponsor_click_unique')===1,'Exact one click one daily observer');$_COOKIE=[];$second=$views->grantCommercialConsent();$next=$proof();$persist->invoke($metrics,$next,'impression',$second);p13_assert($count('sponsor_impression')===3&&$count('sponsor_impression_unique')===2,'Second observer adds distinct daily counter');$zh=$proof('zh_CN');$persist->invoke($metrics,$zh,'impression',$second);p13_assert($count('sponsor_impression','zh_CN')===1&&$count('sponsor_impression_unique','zh_CN')===1,'Language buckets distinct');});
p13_case('commercial_durable_rows_have_only_bounded_opaque_dimensions',function()use($db,$events,$key,$today,$natural,$naturalBefore,$metrics,$admin,$id){$rows=$db->rows("SELECT * FROM $events WHERE policy_version=%s AND dimension_key=%s AND event_day=%s",[Metrics::POLICY,$key,$today]);p13_assert(count($rows)===9,'Exact expected event and unique dedupe rows');foreach($rows as$row){p13_assert($row['dimension_type']==='sponsor'&&$row['dimension_key']===$key,'Only placement and stable sponsor identity');p13_assert(preg_match('/^[a-f0-9]{64}$/D',$row['dedupe_key'])===1,'Daily opaque dedupe, no raw IP/cookie/user');p13_assert($row['expires_at']>$row['occurred_at'],'Short-lived event expiry exists');}p13_assert($natural()===$naturalBefore,'Commercial events do not change any natural aggregate');wp_set_current_user($admin);$report=$metrics->summary(7,'en_US');$found=[];foreach($report['rows']as$r){if($r['dimension_key']===$key)$found[$r['metric_name']]=$r['total'];}p13_assert($found['sponsor_impression']===3&&$found['sponsor_impression_unique']===2&&$found['sponsor_click']===1,'Actual report uses exact fixture counters');p13_assert($report['partial']===true&&$report['coverage']!==null,'Short coverage honestly partial');p13_reject(fn()=>$metrics->summary(365,'en_US'),'Unbounded report rejected');wp_set_current_user(0);p13_reject(fn()=>$metrics->summary(7,'en_US'),'Anonymous cannot read commercial reports');});
p13_case('commercial_transaction_rolls_back_event_budget_and_aggregate_on_failure',function()use($db,$daily,$events,$metrics,$persist,$views,$proof,$key,$count){wp_set_current_user(0);$_COOKIE=[];$observer=$views->grantCommercialConsent();$data=$proof();$before=$count('sponsor_click');$eventBefore=(int)$db->value("SELECT COUNT(*) FROM $events WHERE policy_version=%s AND dimension_key=%s",[Metrics::POLICY,$key]);$inject=static fn(string$sql):string=>str_starts_with($sql,'INSERT INTO '.$daily)?'SELECT phase13_controlled_failure FROM no_such_phase13_qa_table':$sql;$old=$GLOBALS['wpdb']->suppress_errors(true);add_filter('query',$inject,PHP_INT_MAX);try{p13_reject(fn()=>$persist->invoke($metrics,$data,'click',$observer),'Injected aggregate failure surfaces');}finally{remove_filter('query',$inject,PHP_INT_MAX);$GLOBALS['wpdb']->suppress_errors($old);}p13_assert($count('sponsor_click')===$before&&(int)$db->value("SELECT COUNT(*) FROM $events WHERE policy_version=%s AND dimension_key=%s",[Metrics::POLICY,$key])===$eventBefore,'No partial observation or aggregate');p13_assert($persist->invoke($metrics,$data,'click',$observer),'Same proof safely retries after rollback');p13_assert($count('sponsor_click')===$before+1,'Retry commits exactly one');});
p13_case('commercial_current_state_revocation_staff_bot_privacy_guards',function()use($views,$metrics,$sponsors,$proof,$persist,$admin,$id,$d){wp_set_current_user(0);$_COOKIE=[];$observer=$views->grantCommercialConsent();$data=$proof();$_SERVER['HTTP_DNT']='1';p13_reject(fn()=>$persist->invoke($metrics,$data,'click',$observer),'DNT blocks measurement');unset($_SERVER['HTTP_DNT']);$_SERVER['HTTP_SEC_GPC']='1';p13_reject(fn()=>$persist->invoke($metrics,$data,'click',$observer),'GPC blocks measurement');unset($_SERVER['HTTP_SEC_GPC']);$_SERVER['HTTP_USER_AGENT']='Googlebot';p13_reject(fn()=>$persist->invoke($metrics,$data,'click',$observer),'Known bot excluded');$_SERVER['HTTP_USER_AGENT']='Mozilla/5.0 Chrome/155.0.0.0 Safari/537.36';wp_set_current_user($admin);p13_assert($metrics->attributes($sponsors->publicEntry($id,'en_US'))===[],'Administrative preview cannot emit tracking proofs');$sponsors->setEnabled(false,$sponsors->snapshot()['revision']);wp_set_current_user(0);p13_reject(fn()=>$persist->invoke($metrics,$data,'click',$observer),'Disabled placement invalidates prior signed proof');wp_set_current_user($admin);$sponsors->setEnabled(true,$sponsors->snapshot()['revision']);$new=$d;$new['translations']['en_US']['description'].=' New revision';$sponsors->saveEntry($id,$sponsors->snapshot()['revision'],$new,true);wp_set_current_user(0);p13_reject(fn()=>$persist->invoke($metrics,$data,'click',$observer),'Changed reviewed revision invalidates old response');$views->withdrawAnalyticsConsent();p13_assert($views->commercialObserver()===null&&$views->analyticsObserver()===null,'Shared withdrawal revokes all measurement purposes');});
p13_case('commercial_daily_limit_and_replay_do_not_inflate_natural_metrics',function()use($views,$metrics,$persist,$proof,$db,$daily,$events,$count,$natural,$naturalBefore,$admin,$settings){wp_set_current_user(0);$_COOKIE=[];$observer=$views->grantCommercialConsent();$first=null;for($i=0;$i<100;$i++){$data=$proof();if($i===0)$first=$data;p13_assert($persist->invoke($metrics,$data,'click',$observer),'Within bounded daily budget');}$before=$count('sponsor_click');p13_assert(!$persist->invoke($metrics,$first,'click',$observer),'At quota replay remains idempotent');p13_reject(fn()=>$persist->invoke($metrics,$proof(),'click',$observer),'Observation101 rejected');p13_assert($count('sponsor_click')===$before,'Quota failure rolls back new event');p13_assert($natural()===$naturalBefore,'Commercial volume leaves natural ranks and search aggregates untouched');$validBeforeDisable=$proof();wp_set_current_user($admin);$s=Settings::snapshot();$off=$s['published'];$off['tracking']=false;$settings->save($off,$s['revision'],'publish');wp_set_current_user(0);p13_reject(fn()=>$persist->invoke($metrics,$validBeforeDisable,'click',$observer),'Global disabled measurement cannot collect');});
